 pub(super)fn import_native_crane_data(&mut self,v:&Value){
  let Some(s)=&mut self.native_world else{return;};
  // No fabricated frame coordinates: malformed or absent source data leaves
  // the original caller unavailable as a whole.
  s.crane_frames=v["nativeCraneBuildFrames"].as_array().filter(|a|a.len()==12).and_then(|frames|frames.iter().map(|f|{
   f.as_array().filter(|a|a.len()==6)?.iter().map(|r|{
    let a=r.as_array().filter(|a|a.len()==4)?;let mut out=[0i16;4];
    for(i,n)in a.iter().enumerate(){out[i]=i16::try_from(n.as_i64()?).ok()?;}Some(out)
   }).collect::<Option<Vec<_>>>()
  }).collect::<Option<Vec<_>>>()).unwrap_or_default();
  s.load_native_bridge_art(v);
  for(key,alive)in[("nativeBuildingRuinStamps",false),("nativeBuildingAliveStamps",true)]{
   for(k,v)in v[key].as_object().into_iter().flatten(){
    let Ok(k)=k.parse::<i8>()else{continue;};
    let Some(c)=v["codes"].as_array().and_then(|a|a.iter().map(|n|u8::try_from(n.as_u64()?).ok()).collect::<Option<Vec<_>>>())else{continue;};
    let Some(w)=v["w"].as_u64().and_then(|n|usize::try_from(n).ok())else{continue;};
    let Some(h)=v["h"].as_u64().and_then(|n|usize::try_from(n).ok())else{continue;};
    let Some(pointer)=v["pointer"].as_u64().and_then(|n|u32::try_from(n).ok())else{continue;};
    if w>0&&h>0&&w<=10&&h<=10&&w*h==c.len(){let record=(pointer,w,h,c);if alive{s.alive_stamps.insert(k,record);}else{s.ruin_stamps.insert(k,record);}}
   }
  }
 }
 pub(super)fn stamp_native_building_ruin(&mut self,s:&mut State,slot:usize){let Some(b)=s.buildings.get(slot)else{return;};let Some((pointer,w,h,codes))=s.ruin_stamps.get(&b.record.kind)else{return;};let p=b.record.position;let source_y=p[1].wrapping_add(if b.record.kind==0{0}else{32});let y=if [0x47840c,0x47856c,0x47828c].contains(pointer){source_y}else{source_y.wrapping_sub(32)};self.stamp_native_crane_codes(p[0],y,*w,*h,codes);}
