   let all=g.native_display_queue();let chassis=all.iter().find(|r|r["kind"]=="unit"&&r["id"]==carrier).expect("actual55f10 crane row");let layers=chassis["nativeLayers"].as_array().expect("source-backed3-layer crane, no manifest/time fallback");assert_eq!(layers.len(),3);assert!(chassis.get("nativeCraneBoundary").is_none());let u=&g.units[ci];let hw=g.native_hardware_pool[u.native_hardware_slot.unwrap()].attributes;let phase=if (c.work9a as i8)<0{0}else{c.work9a&63};assert!(layers.iter().any(|r|r["sprite"]==5826+i16::from(phase)),"post-handler9a arm;86 is a separate animation");assert!(layers.iter().any(|r|r["sprite"]==5818+i16::from(hw.byte(21))),"actual post-commonW21");assert!(layers.iter().any(|r|r["sprite"]==5794+i16::from(original_combat::facing(u.angle))*3+u.native_frame32),"actual rawframe32");let(rng,crt)=(g.original_rng.words,g.native_cosmetic_rng);assert_eq!(g.native_display_queue(),all,"snapshot must retain the one actual callback submission");assert_eq!((g.original_rng.words,g.native_cosmetic_rng),(rng,crt));
