 fn field()->Game{let mut g=Game::new(0,1,45);g.map.original=true;g.map.width=64;g.map.height=64;g.map.terrain_codes=vec![0;4096];g.map.native_terrain_plane=vec![0;16384];g.map.original_tiles=vec![0;4096];g.map.native_tile_plane=vec![0;16384];g.map.bridge_base=vec![-1;4096];g.units.clear();g.buildings.clear();g.objects.clear();g.crates.clear();g.walls.clear();g.sectors.clear();g.native_group_rosters.clear();g.native_world=None;g.ai_teams.clear();g.multiplayer=true;g.original_rng.multiplayer=true;g.native_feedback.ui_clock=500;g.initialize_native_feedback();g.set_native_listener_settings(&json!({"0":{"soundEnabled":false,"view":{"camera":[0,0],"size":[1024,1024]},"hardwareContext":"1:0"},"1":{"soundEnabled":true,"view":{"camera":[0,0],"size":[1024,1024]},"hardwareContext":"1:0"}}));g.import_native_world(&Value::Null);g.events.clear();g}
 fn recipients(g:&Game,sample:i64)->Vec<u64>{g.events.iter().filter(|e|e["kind"]=="nativeSample"&&e["sampleId"]==sample).map(|e|e["recipientTeam"].as_u64().unwrap()).collect()}
 #[test]fn owner4_expiry_keeps_guest_audio_when_host_is_muted_and_world_runs_once(){
  let(mut quiet,mut loud)=(field(),field());loud.set_native_listener_settings(&json!({"0":{"soundEnabled":true,"view":{"camera":[0,0],"size":[1024,1024]},"hardwareContext":"1:0"}}));
  for g in[&mut quiet,&mut loud]{let mut raw=[0u8;44];raw[6..8].copy_from_slice(&200i16.to_le_bytes());raw[8..10].copy_from_slice(&200i16.to_le_bytes());let s=g.native_world.as_mut().unwrap();s.put_effect(0,Particle::from_bytes(raw));s.last_projection=[0,0];s.effect_maximum=11;g.finish_native_building_part_expiry(0,effects::View{camera:[0,0],clip:[0,0,1024,1024],world:[1024,1024],sine:0,cosine:0});}
  assert_eq!(recipients(&quiet,1),[1]);assert_eq!(recipients(&loud,1),[0,1]);assert_eq!((quiet.native_audio.effect_counter,quiet.native_listener_audio.guest_audio.effect_counter),(0,1));assert_eq!((loud.native_audio.effect_counter,loud.native_listener_audio.guest_audio.effect_counter),(1,1));assert!((quiet.native_audio.opportunity_gate!=0)&&(loud.native_audio.opportunity_gate!=0));
  let bytes=|g:&Game|g.native_world.as_ref().unwrap().effects.iter().map(|p|p.as_ref().map(Particle::bytes)).collect::<Vec<_>>();assert_eq!(bytes(&quiet),bytes(&loud));assert_eq!(quiet.original_rng.words,loud.original_rng.words);assert_eq!(quiet.native_world.as_ref().unwrap().last_projection,loud.native_world.as_ref().unwrap().last_projection);
 }
